<template><div><div class='flex justify-between mb-4'><h2 class='text-xl'>Consultas</h2><router-link to='/appointments/new' class='px-3 py-2 bg-zinc-900 text-white rounded-xl'>Nova consulta</router-link></div><div class='grid md:grid-cols-3 gap-2 mb-3'><BaseInput v-model='filters.date' placeholder='date'/><BaseInput v-model='filters.doctor_id' placeholder='doctor_id'/><BaseInput v-model='filters.status' placeholder='status'/></div><BaseButton @click='load'>Filtrar</BaseButton><LoadingState v-if='loading'/><ErrorState v-else-if='error' :message='error'/><BaseCard v-else-if='items.length===0'>Nenhuma consulta</BaseCard><BaseCard v-for='a in items' :key='a.id' class='mt-2'>{{ a.id }} - {{ a.scheduled_at }}</BaseCard></div></template>
<script setup>import { reactive,ref,onMounted } from 'vue';import { appointmentService } from '../services/appointmentService';import BaseInput from '../components/BaseInput.vue';import BaseButton from '../components/BaseButton.vue';import BaseCard from '../components/BaseCard.vue';import LoadingState from '../components/LoadingState.vue';import ErrorState from '../components/ErrorState.vue';
const filters=reactive({date:'',doctor_id:'',status:''});const items=ref([]),loading=ref(false),error=ref('');
const load=async()=>{loading.value=true;error.value='';try{const d=await appointmentService.list(filters);items.value=d.items||d||[]}catch{error.value='Erro ao buscar consultas'}finally{loading.value=false}};onMounted(load)
</script>
